INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "鹿晏弘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的鹿晏弘：受任兴元留后。", "biography": null, "status": "draft", "id": "68409589-8756-57e2-8d03-2071eb41e5d8"}, {"name": "乐彦祯", "aliases": ["乐行达"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的乐彦祯：获赐名者。", "biography": null, "status": "draft", "id": "bc42c29a-a3a4-51c5-ad15-16bf1105e036"}, {"name": "杨师立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的杨师立：被征为右仆射。", "biography": null, "status": "draft", "id": "988bad2d-f389-5d84-8c56-b7266ec23c82"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "周岌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的周岌：求援者。", "biography": null, "status": "draft", "id": "467ecfe0-f498-55ea-98c7-622123746416"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "晚唐至五代", "birth_year": 852, "death_year": 912, "description": "朱温，后赐名朱全忠，又名朱晃，后梁建立者。籍贯宋州砀山午沟里；父亲朱诚以《五经》教授乡里，父亡后家贫，与母亲、兄长在萧县刘崇家佣食。877年随兄朱存加入黄巢军，882年归唐并获赐名全忠，883年入镇汴州。907年称帝，912年在宫廷政变中被杀。", "biography": "朱温，后赐名朱全忠，又名朱晃，后梁建立者。籍贯宋州砀山午沟里；父亲朱诚以《五经》教授乡里，父亡后家贫，与母亲、兄长在萧县刘崇家佣食。877年随兄朱存加入黄巢军，882年归唐并获赐名全忠，883年入镇汴州。907年称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "诸葛爽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的诸葛爽：屯兵阻拦。", "biography": null, "status": "draft", "id": "f4b6b80e-a632-583c-a8b3-ab4b06a6ec46"}, {"name": "黄巢", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "biography": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "status": "draft", "id": "f1a6e500-8866-5790-8423-7db3ce39a131"}, {"name": "郝蠲", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的郝蠲：奉命袭绵州。", "biography": null, "status": "draft", "id": "12728d48-7421-53d3-a94d-89c3c4cd9afc"}, {"name": "高仁厚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的高仁厚：受任东川留后并领军。", "biography": null, "status": "draft", "id": "ff014a27-d630-52e3-8a2a-fc160fbb8c30"}, {"name": "杨茂言", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的杨茂言：行军副使。", "biography": null, "status": "draft", "id": "cb32da06-a59f-5564-99fd-86f984fb5784"}, {"name": "李唐宾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的李唐宾：归降者。", "biography": null, "status": "draft", "id": "7fd6597f-12ac-5146-92eb-9aea9b8b7427"}, {"name": "王虔裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的王虔裕：归降者。", "biography": null, "status": "draft", "id": "cd08d2b8-ead1-536d-810b-c6f6d3dcbe85"}, {"name": "王镇", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的王镇：拘执刺史并归降。", "biography": null, "status": "draft", "id": "76047161-4b01-59bd-9cd4-c840538adec1"}, {"name": "黄碣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的黄碣：被拘执的婺州刺史。", "biography": null, "status": "draft", "id": "ef6a7e30-fbb2-51eb-8fbc-1ad1ccc58632"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "刘汉宏", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的刘汉宏：派遣者。", "biography": null, "status": "draft", "id": "2bf00f74-7c42-53bf-a012-844e1de44392"}, {"name": "娄赉", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的娄赉：杀王镇并取代其位。", "biography": null, "status": "draft", "id": "d0fb6a3b-f486-5734-a4e6-5d5a9109b75f"}, {"name": "蒋环", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的蒋环：邀兵并共同进攻。", "biography": null, "status": "draft", "id": "4f14242e-83af-5e65-b821-2de1b89870a4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "鹿晏弘获任兴元留后", "start_year": 884, "end_year": 884, "time_original": "中和四年春正月", "dynasty": "唐", "description": "唐廷任鹿晏弘为兴元留后。", "phases": [], "location_name": "兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "abf96468-dc5f-5c81-8e56-9c89421572c4"}, {"title": "乐行达获赐名彦祯", "start_year": 884, "end_year": 884, "time_original": "中和四年正月条，具体日未载", "dynasty": "唐", "description": "唐廷赐魏博节度使乐行达名彦祯；乐行达与乐彦祯为同一人。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "未确定单一发生地。", "status": "draft", "id": "296fd663-60a2-5cb5-b947-4a7487eba43c"}, {"title": "唐廷征杨师立为右仆射", "start_year": 884, "end_year": 884, "time_original": "中和四年正月条，具体日未载", "dynasty": "唐", "description": "杨师立不满陈敬瑄兄弟权势，以及陈敬瑄许诺以东川酬赏高仁厚之事。田令孜担心杨师立作乱，唐廷征杨师立为右仆射。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "未确定单一发生地。", "status": "draft", "id": "4da0f936-06f8-52fb-9b53-b20673124451"}, {"title": "李克用应援出兵，受阻后改道东渡", "start_year": 884, "end_year": 884, "time_original": "中和四年二月", "dynasty": "唐", "description": "周岌、时溥、朱全忠难以抵挡黄巢，共向李克用求援。二月，李克用领蕃、汉兵五万出天井关；诸葛爽以河桥未修好为由屯万善拒之，李克用改从陕、河中渡河向东。", "phases": [], "location_name": "天井关、万善、陕及河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "db12f612-fcb7-5085-bd2a-d5998e6344ff"}, {"title": "杨师立拒绝受代，起兵并进攻绵州", "start_year": 884, "end_year": 884, "time_original": "中和四年二月条，具体日未载", "dynasty": "唐", "description": "杨师立拒绝受代，杀官告使与监军使，以讨陈敬瑄为名起兵，进屯涪城；遣郝蠲袭绵州，未能攻克。", "phases": [], "location_name": "涪城、绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "31619126-6e03-5c2e-a3fe-383a2ff1b8bb"}, {"title": "陈敬瑄获授三道统军职权", "start_year": 884, "end_year": 884, "time_original": "中和四年二月丙午", "dynasty": "唐", "description": "唐廷任陈敬瑄为西川、东川、山南西道都指挥、招讨、安抚、处置等使。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "未确定单一发生地。", "status": "draft", "id": "0bc9fb0b-ce6c-552e-972f-6d0ba0df32ce"}, {"title": "杨师立发布讨陈敬瑄檄文", "start_year": 884, "end_year": 884, "time_original": "中和四年三月甲子", "dynasty": "唐", "description": "杨师立向行在百官及诸道将吏士庶移檄，列陈敬瑄十罪，自称集将士与八州坛丁十五万人，将长驱问罪。十五万人为檄文自称数目。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "未确定单一发生地。", "status": "draft", "id": "7aa75178-0e18-5c17-a192-716210335060"}, {"title": "唐廷削杨师立官爵，命高仁厚率军讨伐", "start_year": 884, "end_year": 884, "time_original": "中和四年三月甲子檄文之后，具体日未载", "dynasty": "唐", "description": "唐廷削杨师立官爵，任眉州防御使高仁厚为东川留后，领兵五千讨伐，以杨茂言为行军副使。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "fea82380-2a30-55bd-9ecc-07d8ab49fd30"}, {"title": "朱全忠攻取瓦子寨，李唐宾、王虔裕归降", "start_year": 884, "end_year": 884, "time_original": "中和四年三月条，具体日未载", "dynasty": "唐", "description": "朱全忠攻取黄巢瓦子寨；黄巢将领李唐宾、王虔裕归降朱全忠。", "phases": [], "location_name": "瓦子寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "d51c62b7-be6a-56a6-a328-0e11042ebf84"}, {"title": "王镇拘执婺州刺史黄碣，归降钱镠", "start_year": 884, "end_year": 884, "time_original": "中和四年三月条，具体日未载", "dynasty": "唐", "description": "婺州人王镇拘执刺史黄碣，归降钱镠。", "phases": [], "location_name": "婺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "c5dc42ce-5b37-55bb-9b44-4ed54baa8c42"}, {"title": "刘汉宏遣娄赉杀王镇并取代其位", "start_year": 884, "end_year": 884, "time_original": "中和四年三月条，具体日未载", "dynasty": "唐", "description": "刘汉宏遣将娄赉杀王镇并取代其位。", "phases": [], "location_name": "婺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "a61cb6ed-40b2-562c-9cd5-a249f906cb70"}, {"title": "蒋环邀钱镠军攻婺州，擒娄赉", "start_year": 884, "end_year": 884, "time_original": "中和四年三月条，具体日未载", "dynasty": "唐", "description": "浦阳镇将蒋环召钱镠军共同进攻婺州，擒获娄赉后返回。", "phases": [], "location_name": "婺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "史载地名；未核定古城址与坐标。", "status": "draft", "id": "d5f9d72d-bdea-5d4b-81d9-c97213ecac90"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
